import * as T from 'three';
import {createBasin,SPAWN,STOPS} from './world.js';
import {createExplorationNavigation} from './navigation.js';
const $=s=>document.querySelector(s),canvas=$('#sea'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
const wrap=a=>((a+Math.PI)%(2*Math.PI)+2*Math.PI)%(2*Math.PI)-Math.PI;
let ready=false,last=null,time=0,frames=0,pointer=null,guide=null,history=[];
try{
 const gl=canvas.getContext('webgl2',{antialias:true,alpha:false});if(!gl)throw Error('WebGL2 unavailable');
 const renderer=new T.WebGLRenderer({canvas,context:gl,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.87;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
 const loader=new T.TextureLoader(),names=['sandNormal','sandRoughness','rockNormal','rockRoughness','coralNormal','coralRoughness'];const loaded=await Promise.all(names.map((n,i)=>loader.loadAsync('../../assets/reef-texture-'+i+'.png').then(t=>{t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());return[n,t]})));const caustics=await loader.loadAsync('../../assets/water-caustics.png');caustics.wrapS=caustics.wrapT=T.RepeatWrapping;const textures=Object.fromEntries(loaded);textures.caustics=caustics;
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(61,1,.08,500),world=createBasin(scene,textures);
 const nav=createExplorationNavigation({stops:STOPS,spawn:SPAWN,speed:4,resolvePosition:p=>world.resolve(p),movePosition:(p,old)=>world.move(p,old)});nav.setReduced(reduced.matches);nav.reset();
 const apply=()=>{const p=nav.pose();camera.position.fromArray(p.position);camera.lookAt(new T.Vector3(...p.target));camera.updateMatrixWorld()};
 function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();apply()}resize();addEventListener('resize',resize);
 const distance=(a,b)=>Math.hypot(a[0]-b[0],a[2]-b[2]);
 function phase(name){nav.stop();guide.phase=name;guide.phaseStart=guide.elapsed;guide.origin=nav.getState().position;guide.turn=0;history.push({phase:name,elapsed:guide.elapsed,position:guide.origin,yaw:nav.getState().yaw});if(name==='advance'||name==='return')nav.key('KeyW',true);if(name==='lookBack'||name==='panorama')nav.key('ArrowRight',true);if(name==='sideSwim')nav.key('KeyD',true)}
 function start(){nav.reset();guide={phase:'',elapsed:0,paused:false,phaseStart:0,origin:SPAWN.position,turn:0,completed:false,failure:null};history=[];phase('advance');last=null}
 const labels={advance:'沿礁脊前进',lookBack:'180° 回望',holdBack:'观察返回方向',sideSwim:'横移观察盆地',panorama:'360° 环视',aimReturn:'转向起点',return:'返回同一出发点',completed:'证明段结束 · 待视觉审查',blocked:'证明段未完成'};
 function tick(dt){if(!guide||guide.paused||guide.completed){nav.tick(dt);return}guide.elapsed+=dt;const before=nav.getState();if(guide.phase==='aimReturn'||guide.phase==='return'){const d=SPAWN.position.map((v,i)=>v-before.position[i]),heading=Math.atan2(d[0],-d[2]),error=wrap(heading-before.yaw);nav.look(T.MathUtils.clamp(error,-1.1*Math.min(dt,.05),1.1*Math.min(dt,.05)),0)}nav.tick(dt);const after=nav.getState();guide.turn+=Math.abs(wrap(after.yaw-before.yaw));
  if(guide.phase==='advance'&&distance(after.position,SPAWN.position)>=41.0)phase('lookBack');else if(guide.phase==='lookBack'&&guide.turn>=Math.PI-.015)phase('holdBack');else if(guide.phase==='holdBack'&&guide.elapsed-guide.phaseStart>=.9)phase('sideSwim');else if(guide.phase==='sideSwim'&&distance(after.position,guide.origin)>=24)phase('panorama');else if(guide.phase==='panorama'&&guide.turn>=Math.PI*2-.015)phase('aimReturn');else if(guide.phase==='aimReturn'&&guide.elapsed-guide.phaseStart>=.7)phase('return');else if(guide.phase==='return'&&distance(after.position,SPAWN.position)<.7){phase('completed');guide.completed=true;nav.pause(true)}
  if(guide.elapsed>58&&!guide.completed){phase('blocked');guide.failure='Bounded proof route could not return without repositioning';guide.completed=true;nav.pause(true)}
 }
 function sync(){const n=nav.getState();$('#phase').textContent=guide?labels[guide.phase]:'自由游动 · 未验收候选';$('#time').textContent=guide?guide.elapsed.toFixed(1)+' 秒':'';$('#pause').textContent=n.paused?'继续':'暂停'}
 $('#proof').onclick=()=>{start();sync()};$('#free').onclick=()=>{guide=null;nav.free();sync()};$('#home').onclick=()=>{guide=null;nav.reset();apply();sync()};$('#pause').onclick=()=>{const value=!nav.getState().paused;nav.pause(value);if(guide&&!guide.completed){guide.paused=value;if(!value){const p=guide.phase;nav.stop();if(p==='advance'||p==='return')nav.key('KeyW',true);else if(p==='sideSwim')nav.key('KeyD',true);else if(p==='lookBack'||p==='panorama')nav.key('ArrowRight',true)}}sync()};
 const keys=['KeyW','KeyS','KeyA','KeyD','KeyQ','KeyE','ShiftLeft','ShiftRight','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'];canvas.addEventListener('keydown',e=>{if(keys.includes(e.code)){e.preventDefault();guide=null;nav.key(e.code,true)}else if(e.code==='Space'){e.preventDefault();$('#pause').click()}else if(e.code==='Home'){e.preventDefault();$('#home').click()}});canvas.addEventListener('keyup',e=>nav.key(e.code,false));canvas.addEventListener('blur',()=>nav.stop());
 canvas.addEventListener('pointerdown',e=>{guide=null;nav.free();canvas.focus({preventScroll:true});pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(pointer?.id!==e.pointerId)return;nav.look((e.clientX-pointer.x)*.004,(pointer.y-e.clientY)*.003);pointer={id:e.pointerId,x:e.clientX,y:e.clientY};apply()});for(const event of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{pointer=null});
 document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();guide=null;b.setPointerCapture(e.pointerId);nav.key(b.dataset.key,true)});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>nav.key(b.dataset.key,false))});
 addEventListener('blur',()=>{nav.pause(true);if(guide)guide.paused=true;last=null});document.addEventListener('visibilitychange',()=>{last=null;if(document.hidden){nav.pause(true);if(guide)guide.paused=true}});
 ready=true;$('#loading').hidden=true;sync();renderer.setAnimationLoop(ms=>{const dt=last===null?0:Math.max(0,(ms-last)/1000);last=ms;if(document.hidden)return;tick(dt);if(!reduced.matches&&!nav.getState().paused)time+=Math.min(dt,.1);apply();world.update(time,camera);renderer.render(scene,camera);frames++;sync()});
 window.basinProof={scene,camera,renderer,world,navigation:nav,getState:()=>({ready,frames,time,camera:camera.position.toArray(),target:nav.pose().target,navigation:nav.getState(),guide:guide?{...guide}:null,history:history.slice(),stats:world.stats,renderer:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles},fov:camera.fov})};
 addEventListener('pagehide',()=>{renderer.setAnimationLoop(null);world.dispose();Object.values(textures).forEach(t=>t.dispose());renderer.dispose()});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();renderer.setAnimationLoop(null);$('#error').hidden=false});
}catch(e){console.error('Basin proof failed',e);$('#loading').hidden=true;$('#error').hidden=false;window.basinFailure=String(e)}
